      "惰性删除和主动过期如何互补，二者分别覆盖哪些访问模式和内存回收场景",
      "长期无人访问的过期 key 为什么会继续占用内存，如何用 INFO 和内存曲线判断",
      "大量已过期 key 被集中访问时，Redis 延迟、业务 miss 和数据库回源会如何变化",
      "Big Key 过期后第一次访问为什么可能推高 P99/P999，`lazyfree-lazy-expire` 和 `UNLINK` 能解决哪些释放成本",
      "主节点删除过期 key 后，AOF 和副本如何获得删除结果，读副本排查时要确认哪些条件",
