      "`redis-cli --bigkeys`、`--keystats`、`SCAN` 和 `MEMORY USAGE` 分别适合做什么",
      "线上扫描 Big Key 如何限速、采样和按业务前缀分批",
      "大 String、大 Hash、大 List、大 Set 和大 ZSet 分别如何拆分或裁剪",
      "`DEL` 与 `UNLINK` 删除大对象的成本差异是什么，如何验证延迟变化",
      "Big Key 过期、淘汰或迁移为什么会造成 P99/P999 尖刺",
      "Big Key 和 Hot Key 叠加时如何判断瓶颈并组合治理",
