      "Redis Cluster 中 slot 分布均匀时，为什么单个热 Key 仍会压垮一个节点",
      "`redis-cli --hotkeys`、`OBJECT FREQ`、客户端埋点和代理统计分别适合什么场景",
      "线上如何用 `INFO`、`SLOWLOG`、`LATENCY`、`CLIENT LIST` 和业务指标证明热 Key 存在",
      "读热点如何用本地缓存、多级缓存、副本读、多副本 key 和请求合并治理",
